"use strict";

const path = require("path");
const querystring = require("querystring");
const { URL } = require("url");

exports.summarize = function summarize() {
  const encoded = querystring.stringify({
    q: "one two",
    tag: ["a", "b"],
    empty: ""
  });
  const parsed = querystring.parse(encoded);
  const normalized = path.posix.normalize("/root/a/../b/./file.txt");
  const url = new URL("https://example.test" + normalized + "?" + encoded);
  const tags = Array.isArray(parsed.tag) ? parsed.tag.join("+") : String(parsed.tag || "");

  return [
    "pathquery",
    url.pathname,
    parsed.q,
    tags,
    url.searchParams.get("empty") === ""
  ].join(":");
};
